-- GENERATED by `wfj generate` from data/book/. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("book", {
  ["9c06bb26cb6093c9"] = { "Mai stato così orgoglioso di far parte del mestiere come in questi ultimi anni. Il bisogno di assassini, spie ed esploratori non è mai stato così diffuso. Si penserebbe che in tempo di guerra la richiesta fosse più alta, ma sorprendentemente la guerra non è un periodo in cui prosperiamo come adesso: i tempi in cui la pace comincia a sgretolarsi.\n\nMi hanno detto che avresti fatto un giro da queste parti per imparare qualcosa. Quando hai tempo, vieni a trovarmi vicino alle stalle dietro l'abbazia.\n\n-Jorik Kerridan, istruttore dei ladri", "." },
  ["9c3d6e995972970d"] = { "Diecimila anni prima che orchi e umani si scontrassero nella loro Prima Guerra, il mondo di Azeroth accoglieva un solo, immenso continente circondato da mari infiniti e impetuosi. Quella massa di terra, nota come Kalimdor, ospitava diverse razze e creature, tutte in lotta per la sopravvivenza tra gli elementi selvaggi del mondo appena desto. Al centro dell'oscuro continente si trovava un misterioso lago di energie incandescenti.", "." },
  ["9c84c3994b633a5f"] = { "<HTML>\n<BODY>\n<H1 align=\"center\">GRADI MILITARI DELL'ORDA</H1><BR/>\n<P align=\"center\">UFFICIALI</P><BR/>\n<P align=\"center\">Gran Signore della Guerra</P>\n<P align=\"center\">Signore della Guerra</P>\n<P align=\"center\">Generale</P>\n<P align=\"center\">Tenente Generale</P>\n<P align=\"center\">Campione</P>\n<P align=\"center\">Centurione</P>\n<P align=\"center\">Legionario</P>\n<P align=\"center\">Guardia di Sangue</P>\n<P align=\"center\">Guardia di Pietra</P><BR/>\n<P align=\"center\">TRUPPA</P><BR/>\n<P align=\"center\">Primo Sergente</P>\n<P align=\"center\">Sergente Istruttore</P>\n<P align=\"center\">Sergente</P>\n<P align=\"center\">Grunt</P>\n<P align=\"center\">Esploratore</P>\n</BODY>\n</HTML>", "." },
  ["9c8bf8d5346384cb"] = { "La caduta di ⟦Ameth'Aran=Ameth'aran⟧\n\nLa terra tremò mentre gli alberi antichi della foresta incantata venivano sradicati e abbattuti. I boschetti e le radure curati dai figli e dalle figlie di Cenarius e le torri di pietra dei Figli delle Stelle furono rasi al suolo che sussultava. Là c'era la nostra regina, radiosa persino nella disperazione, nel caos che erano le battaglie. Il cielo incantato cambiava colore a ogni scarica di magia, con esplosioni che minacciavano di squarciare il mondo.", "." },
  ["9cbcbe3c95910fd6"] = { "Saluti e omaggi, avventurieri!\n\nIo, ⟦Krinkle Goodsteel=Krinkle Ferrofiz⟧, ho bisogno di qualcuno disposto a rischiare la pelle per portare a termine alcuni dei miei compiti più ardui. Visti i miei tanti impegni e la mole di lavoro che sono riuscito ad accollarmi, garantisco che chiunque abbia il coraggio di procurarmi gli oggetti di questo elenco e di riportarmeli intatti sarà pagato profumatamente.\n\nL'elenco si trova nelle pagine seguenti...", "." },
  ["9cc681308f3ab1dd"] = { "Le ⟦Badlands=Maleterre⟧ sono piene di nemici. Gli ogre vagano tra le sabbie roventi, tendendo imboscate agli incauti. I nani ⟦Dark Iron=Ferroscuro⟧ occupano una caserma a est di Kargath e combattono i loro cugini dalla pelle più chiara a Loch Modan, a nord. Bestie brutali e primitive chiamate trogg infestano ogni lembo d'ombra che trovano e lo difendono con ferocia.\n\nE nelle ⟦Badlands=Maleterre⟧ orientali, nella ⟦Lethlor Ravine=Piana di Lethlor⟧, ci sono i draghi. Non sappiamo quanti siano né quanto siano grandi, perché gli esploratori che si avvicinano troppo non tornano mai.", "." },
  ["9ceae0f20e65ab20"] = { "Persa la loro regina, i ⟦Dark Iron=Ferroscuro⟧ fuggirono davanti alla furia dei Granmartello. Corsero a sud verso la roccaforte del loro re, solo per imbattersi negli eserciti di ⟦Ironforge=Forgiardente⟧, giunti in aiuto di Grim Batol. Schiacciate tra due eserciti, le forze superstiti dei ⟦Dark Iron=Ferroscuro⟧ furono completamente annientate.", "." },
})
